-- Name: users; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.users (
    id character varying DEFAULT gen_random_uuid() NOT NULL,
    username text NOT NULL,
    password text NOT NULL,
    email text,
    role text DEFAULT 'user'::text,
    created_at timestamp without time zone DEFAULT now(),
    full_name text
);


ALTER TABLE public.users OWNER TO postgres;

--
-- Name: vat_rates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.vat_rates (
    id character varying DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    rate numeric(5,2) NOT NULL,
    country text DEFAULT 'NL'::text,
    description text,
    is_active boolean DEFAULT true,
    created_at timestamp without time zone DEFAULT now()
);


ALTER TABLE public.vat_rates OWNER TO postgres;

--
-- Name: work_order_items; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.work_order_items (
    id character varying DEFAULT gen_random_uuid() NOT NULL,
    work_order_id character varying NOT NULL,
    item_id character varying,
    description text NOT NULL,
    quantity numeric(10,3) DEFAULT '0'::numeric,
    unit text,
    unit_price numeric(10,2) DEFAULT 0.00,
    line_total numeric(10,2) DEFAULT 0.00,
    line_type text DEFAULT 'standard'::text,
    "position" integer DEFAULT 0,
    position_no text,
    work_date timestamp without time zone,
    technician_names text,
    technician_ids text,
    description_internal text,
    discount_percent numeric(5,2) DEFAULT '0'::numeric,
    source_snippet_id character varying,
    source_snippet_version integer,
    hs_code text,
    country_of_origin text
);


ALTER TABLE public.work_order_items OWNER TO postgres;

--
-- Name: work_order_number_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.work_order_number_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE public.work_order_number_seq OWNER TO postgres;

--
-- Name: work_orders; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.work_orders (
    id character varying DEFAULT gen_random_uuid() NOT NULL,
    order_number text DEFAULT concat('WO-', lpad((nextval('public.work_order_number_seq'::regclass))::text, 4, '0'::text)) NOT NULL,
    project_id character varying,
    title text NOT NULL,
    description text,
    assigned_to text,
    status text DEFAULT 'pending'::text,
    priority text DEFAULT 'medium'::text,
    start_date timestamp without time zone,
    due_date timestamp without time zone,
    completed_date timestamp without time zone,
    estimated_hours integer,
    actual_hours integer,
    created_at timestamp without time zone DEFAULT now(),
    print_layout_id character varying
);


ALTER TABLE public.work_orders OWNER TO postgres;

